  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.45)*110, 170+Math.sin(t*0.6)*50, 0.09, 1.8, 0.8],
