    aS += (Math.sin(d*f - t*sp) + Math.sin(d*f*1.3 - t*sp*0.8 + 0.5)) * w;
    iS += (Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) + Math.cos(d*f*0.5 - t*sp*0.4 + 2.0)) * w;
    sS += Math.sin(d*f*0.3 + Math.atan2(sy-sY, sx-sX)*2 - t*sp*0.5) * w;
  }
  const tw = 8;
  const act = aS/tw, inh = iS/tw, spiral = sS/tw;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.035+t*1.0))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.2)*0.3 + Math.sin((sx-sy)*0.09-t*1.8)*0.3;
  const bg3 = Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.05-t*1.2)*0.4;
