  const ridge = (1.0 - Math.abs(membrane)) * (1.0 - Math.abs(cellA)) * 0.15;
  const blend = membrane*0.6 + cellA*0.2 + cellB*0.1 + ridge*0.1;
  const v = blend*0.5+0.5;
  const pal = [
